<script lang="ts">
  import { onMount,onDestroy } from 'svelte';import { ask } from '@tauri-apps/plugin-dialog';import { roadmapSystemApi as desktop } from '#lib/roadmap-system-api.ts';import { guessOs } from '#lib/api.ts';import Notice from '#lib/ui/Notice.svelte';
  let show=$state<boolean|null>(null),busy=$state(false),error=$state(''),message=$state('');let requestId=0;
  async function load(){const id=++requestId;busy=true;error='';try{const next=await desktop.hiddenFiles();if(id===requestId)show=next;}catch(e){if(id===requestId)error=e instanceof Error?e.message:String(e);}finally{if(id===requestId)busy=false;}}
  async function toggle(){if(show===null || busy)return;const next=!show,id=++requestId;busy=true;error='';message='';try{if(!await ask(`${next?'Show':'Hide'} ordinary hidden files in your file manager?${guessOs()==='macos'?'\n\nFinder will restart to apply this change. Finish file operations first.':''}`,{title:'Change hidden-file visibility?',kind:'warning'}))return;if(id!==requestId)return;const value=await desktop.hiddenFiles(next,true);if(id===requestId){show=value;message=value?'Hidden files are shown.':'Hidden files are hidden.';}}catch(e){if(id===requestId)error=e instanceof Error?e.message:String(e);}finally{if(id===requestId)busy=false;}}
  onMount(()=>{void load();});onDestroy(()=>{requestId++;});
</script>
<div class="tool" aria-busy={busy}><Notice kind="info">Changes the file manager's ordinary hidden-file setting. Windows protected operating-system files keep their existing setting. This preference stays in effect after Oxbox quits.</Notice><p>Status: {show===null?'Not loaded':show?'Hidden files shown':'Hidden files hidden'}</p><div class="row"><button class="btn" disabled={busy} onclick={load}>Refresh status</button><button class="btn btn-primary" disabled={busy || show===null} onclick={toggle}>{show?'Hide hidden files…':'Show hidden files…'}</button></div>{#if message}<Notice kind="success">{message}</Notice>{/if}{#if error}<Notice kind="error">{error}</Notice>{/if}</div>
<style>.tool{display:grid;gap:var(--s-4)}.row{display:flex;gap:var(--s-3)}</style>
